import { Events, SegmentationRepresentations } from '../../enums/index.js';
import { eventTarget, utilities, getRenderingEngine, getEnabledElement, } from '@cornerstonejs/core';
import PlanarFreehandContourSegmentationTool from '../annotation/PlanarFreehandContourSegmentationTool.js';
import BrushTool from './BrushTool.js';
import * as segmentation from '../../stateManagement/segmentation/index.js';
import { getSegmentationRepresentation } from '../../stateManagement/segmentation/getSegmentationRepresentation.js';
import { getActiveSegmentIndex } from '../../stateManagement/segmentation/getActiveSegmentIndex.js';
import { isSegmentIndexLocked } from '../../stateManagement/segmentation/segmentLocking.js';
import { getSegmentIndexVisibility } from '../../stateManagement/segmentation/config/segmentationVisibility.js';
const cs3dLogger = utilities.logger.toolsLog.getLogger('tools.segmentation.LabelmapEditWithContour');
class LabelMapEditWithContourTool extends PlanarFreehandContourSegmentationTool {
    static clearTemporaryContourRecords() {
        LabelMapEditWithContourTool.temporaryContourData.clear();
        LabelMapEditWithContourTool.temporaryContourViewports.clear();
    }
    static getViewportContourKey(viewportId, segmentationId) {
        return `${viewportId}\u0000${segmentationId}`;
    }
    constructor(toolProps = {}) {
        const initialProps = utilities.deepMerge({
            configuration: {
                calculateStats: false,
                allowOpenContours: false,
            },
        }, toolProps);
        super(initialProps);
        this.initializeAddNewAnnotationHandler();
    }
    initializeAddNewAnnotationHandler() {
        const originalAddNewAnnotation = this.addNewAnnotation.bind(this);
        this.addNewAnnotation = (evt) => {
            const { element } = evt.detail;
            const enabledElement = getEnabledElement(element);
            if (enabledElement) {
                const viewportId = enabledElement.viewport.id;
                const activeSeg = segmentation.getActiveSegmentation(viewportId);
                if (!activeSeg) {
                    return null;
                }
                const activeSegIndex = getActiveSegmentIndex(activeSeg.segmentationId);
                if (activeSegIndex === undefined) {
                    return null;
                }
                const isSegmentLocked = isSegmentIndexLocked(activeSeg.segmentationId, activeSegIndex);
                const isSegmentHidden = !getSegmentIndexVisibility(viewportId, {
                    segmentationId: activeSeg.segmentationId,
                    type: SegmentationRepresentations.Labelmap,
                }, activeSegIndex);
                if (isSegmentLocked || isSegmentHidden) {
                    return null;
                }
                LabelMapEditWithContourTool.clearTemporaryContourRecords();
                this.checkContourSegmentation(viewportId, activeSeg).catch((error) => {
                    cs3dLogger.warn('Failed to add the temporary contour representation:', error);
                });
            }
            return originalAddNewAnnotation(evt);
        };
    }
    initializeListeners() {
        LabelMapEditWithContourTool.annotationsToViewportMap.clear();
        eventTarget.addEventListener(Events.ANNOTATION_MODIFIED, this.annotationModified);
        eventTarget.addEventListener(Events.ANNOTATION_COMPLETED, this.annotationCompleted);
    }
    cleanUpListeners() {
        LabelMapEditWithContourTool.annotationsToViewportMap.clear();
        LabelMapEditWithContourTool.clearTemporaryContourRecords();
        eventTarget.removeEventListener(Events.ANNOTATION_MODIFIED, this.annotationModified);
        eventTarget.removeEventListener(Events.ANNOTATION_COMPLETED, this.annotationCompleted);
    }
    async checkContourSegmentation(viewportId, activeSeg) {
        if (!activeSeg) {
            cs3dLogger.info('No active segmentation detected');
            return false;
        }
        const segmentationId = activeSeg.segmentationId;
        if (!activeSeg.representationData.Contour) {
            segmentation.addRepresentationData({
                segmentationId,
                type: SegmentationRepresentations.Contour,
                data: {},
            });
            LabelMapEditWithContourTool.temporaryContourData.add(segmentationId);
        }
        const hasViewportContour = getSegmentationRepresentation(viewportId, {
            segmentationId,
            type: SegmentationRepresentations.Contour,
        });
        if (!hasViewportContour) {
            await segmentation.addContourRepresentationToViewport(viewportId, [
                {
                    segmentationId,
                    type: SegmentationRepresentations.Contour,
                },
            ]);
            LabelMapEditWithContourTool.temporaryContourViewports.add(LabelMapEditWithContourTool.getViewportContourKey(viewportId, segmentationId));
        }
        return true;
    }
    createMemo(element, annotation, options) {
        return;
    }
    onSetToolEnabled() {
        this.initializeListeners();
    }
    onSetToolActive() {
        this.initializeListeners();
    }
    onSetToolDisabled() {
        this.cleanUpListeners();
    }
    annotationModified(evt) {
        const { annotation, renderingEngineId, viewportId } = evt.detail;
        if (annotation?.metadata?.toolName !== LabelMapEditWithContourTool.toolName) {
            return;
        }
        const viewport = getRenderingEngine(renderingEngineId)?.getViewport(viewportId);
        if (!viewport) {
            return;
        }
        LabelMapEditWithContourTool.annotationsToViewportMap.set(annotation.annotationUID, viewport);
    }
    static hasContourContent(contourData) {
        if (contourData.geometryIds?.length) {
            return true;
        }
        const { annotationUIDsMap } = contourData;
        if (!annotationUIDsMap) {
            return false;
        }
        for (const annotationUIDs of annotationUIDsMap.values()) {
            if (annotationUIDs.size) {
                return true;
            }
        }
        return false;
    }
    static cleanupTemporaryContourRepresentation(viewport, annotation) {
        const segmentationId = annotation?.data?.segmentation?.segmentationId;
        if (!segmentationId) {
            return;
        }
        const viewportKey = LabelMapEditWithContourTool.getViewportContourKey(viewport.id, segmentationId);
        const ownsViewportContour = LabelMapEditWithContourTool.temporaryContourViewports.has(viewportKey);
        const ownsContourData = LabelMapEditWithContourTool.temporaryContourData.has(segmentationId);
        if (!ownsViewportContour && !ownsContourData) {
            return;
        }
        const segmentationState = segmentation.state.getSegmentation(segmentationId);
        const contourData = segmentationState?.representationData?.Contour;
        if (contourData &&
            LabelMapEditWithContourTool.hasContourContent(contourData)) {
            return;
        }
        if (ownsViewportContour) {
            LabelMapEditWithContourTool.temporaryContourViewports.delete(viewportKey);
            segmentation.removeContourRepresentation(viewport.id, segmentationId);
        }
        if (!ownsContourData || !segmentationState) {
            return;
        }
        LabelMapEditWithContourTool.temporaryContourData.delete(segmentationId);
        const representationData = utilities.deepClone(segmentationState.representationData);
        delete representationData.Contour;
        segmentation.updateSegmentations([
            {
                segmentationId,
                payload: {
                    representationData,
                },
            },
        ], true);
    }
    annotationCompleted(evt) {
        const { annotation } = evt.detail;
        if (annotation?.metadata?.toolName !== LabelMapEditWithContourTool.toolName) {
            return;
        }
        const annotationUID = annotation.annotationUID;
        const viewport = LabelMapEditWithContourTool.annotationsToViewportMap.get(annotationUID);
        if (!viewport) {
            return;
        }
        const polyline = annotation.data?.contour?.polyline;
        const segmentationData = annotation.data
            ?.segmentation;
        if (polyline?.length >= 3 && segmentationData) {
            BrushTool.viewportContoursToLabelmap(viewport, {
                strokeStartPoint: polyline[0],
                annotationFilter: (annotations) => annotations.filter((candidate) => {
                    const candidateSegmentation = candidate.data?.segmentation;
                    return (candidateSegmentation?.segmentationId ===
                        segmentationData.segmentationId &&
                        candidateSegmentation?.segmentIndex ===
                            segmentationData.segmentIndex);
                }),
            });
        }
        LabelMapEditWithContourTool.cleanupTemporaryContourRepresentation(viewport, annotation);
        LabelMapEditWithContourTool.annotationsToViewportMap.delete(annotationUID);
    }
}
LabelMapEditWithContourTool.toolName = 'LabelMapEditWithContour';
LabelMapEditWithContourTool.annotationsToViewportMap = new Map();
LabelMapEditWithContourTool.temporaryContourData = new Set();
LabelMapEditWithContourTool.temporaryContourViewports = new Set();
export default LabelMapEditWithContourTool;
